const sectionHeadings = new Set(Object.keys(sectionHeadingIds));
const faqStart = rawSourceContent.indexOf("\n1. What is depression in women?");
const articleStart = rawSourceContent.indexOf("All women have");
const articleContent = rawSourceContent.slice(articleStart >= 0 ? articleStart : 0, faqStart > 0 ? faqStart : rawSourceContent.length).trim();
const duplicateHeroLines = new Set([
  "Depression & Low Mood",
  "Depression & Low Mood Treatment for Women in India",
  "The promotion of Emotional Wellbeing, Hope and Mental Health of women at every stage of life.",
  "At Manovaidya, Women's Depression Treatment Focuses On",
  ...keyTakeawayLabels,
  ...focusCards.map(({ label }) => label),
]);

const faqEnd = rawSourceContent.indexOf("\nBook a Consultation", faqStart);
const faqContent = faqStart >= 0 ? rawSourceContent.slice(faqStart, faqEnd > faqStart ? faqEnd : undefined).trim() : "";

const seenSectionIds = new Set();

const articleSections = articleContent.split("\n").reduce(
  (sections, line) => {
    const trimmed = line.trim();
    if (duplicateHeroLines.has(trimmed)) return sections;

    if (sectionHeadings.has(trimmed)) {
      const baseId = sectionHeadingIds[trimmed];
      const id = seenSectionIds.has(baseId) ? `${baseId}-${sections.length}` : baseId;
      seenSectionIds.add(baseId);
      sections.push({ title: trimmed, id, lines: [] });
      return sections;
    }

    sections[sections.length - 1].lines.push(line);
    return sections;
  },
  [{ title: "Introduction", id: "introduction", lines: [] }]
).filter((section) => section.lines.some((line) => line.trim()) || section.title !== "Introduction");

const faqs = faqContent
  .split(/\n(?=\d+\. )/)
  .filter((item) => /^\d+\.\s/.test(item.trim()))
  .map((item) => {
    const [question, ...answer] = item.trim().split("\n");
    return { question, answer: answer.join(" ") };
  });

const paragraphLinkKeys = (() => {
  const linkedRuleKeys = new Set();
  const ruleKeysByText = new Map();

  articleSections.forEach((section, sectionIndex) => {
    section.lines.forEach((line, lineIndex) => {
      const trimmed = line.trim();
      if (!trimmed || sectionHeadings.has(trimmed) || trimmed.length < 82) return;
      const ruleKeys = getArticleLinkRuleKeysForText(trimmed, linkedRuleKeys);
      if (ruleKeys.size) ruleKeysByText.set(`${sectionIndex}-${lineIndex}`, ruleKeys);
    });
  });

  faqs.forEach((faq, faqIndex) => {
    const ruleKeys = getArticleLinkRuleKeysForText(faq.answer, linkedRuleKeys);
    if (ruleKeys.size) ruleKeysByText.set(`faq-${faqIndex}`, ruleKeys);
  });

  return ruleKeysByText;
})();

const slugify = (value) =>
  value
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 56);

